return [{ json: {
  status: "aborted", stage: "run-deterministic", exit_code: $json.exitCode, stderr: $json.stderr,
  message: "The deterministic processing stage failed to run (see stderr). Check that project_path/manifest_path are correct and that Python dependencies (Pillow, imagehash, jsonschema) and ffmpeg are installed in this n8n environment. No source files were modified.",
}}];

const buf = Buffer.from($input.item.binary.data.data, 'base64');
const parsed = JSON.parse(buf.toString('utf8'));
return [{ json: parsed }];

const payload = $json;
const byId = {};
for (const a of payload.assets) byId[a.id] = a;
const clusters = payload.clusters_needing_ai || {};
const aiMode = $('Project Configuration').item.json.ai_mode;
const items = [];
for (const [clusterId, memberIds] of Object.entries(clusters)) {
  const members = memberIds.map(id => byId[id]).filter(Boolean);
  items.push({ json: { cluster_id: clusterId, members, project_root: payload.project_root, ai_mode: aiMode } });
}
return items;

const det = $('Parse Deterministic JSON').item.json;
const byId = {};
for (const a of det.assets) byId[a.id] = a;

// Attach AI results for clusters that were sent to the sub-workflow.
for (const item of $input.all()) {
  const result = item.json;
  if (!result || !result.cluster_id) continue;
  for (const m of (result.members || [])) {
    if (byId[m.asset_id]) byId[m.asset_id].ai = result;
  }
}

// Trivial clusters (every member shares one file hash) never went to AI --
// resolve them deterministically here, mirroring python/src/pipeline.py.
const clusters = det.version_clusters || {};
const needingAi = new Set(Object.keys(det.clusters_needing_ai || {}));
for (const [clusterId, memberIds] of Object.entries(clusters)) {
  if (needingAi.has(clusterId)) continue;
  const record = {
    cluster_id: clusterId, relationship: "likely_duplicate_set", confidence: 1.0, creative_type: "unknown",
    visual_summary: "All members are byte-identical (SHA-256 match); no AI opinion needed.",
    reason: "Deterministic: every member of this cluster shares an identical file hash.",
    recommended_review: false, ai_mode: "deterministic", ai_error: null,
    members: memberIds.map((id, idx) => ({ asset_id: id, likely_role: idx === 0 ? "final" : "duplicate", role_confidence: 1.0, differs_visually: false })),
  };
  for (const id of memberIds) if (byId[id]) byId[id].ai = record;
}

return [{ json: { ...det, assets: Object.values(byId) } }];

// Deterministic weighted scoring -- the n8n-side port of python/src/classification.py.
// AI confidence is ONE input, never the decision. Constants below must be kept
// in sync with python/src/config.py -- see docs/architecture-decision.md §7.
const FINAL_RE = /final\s*final|\bfinal\b|\bFINAL\b|approved|delivered?|\blatest\b/i;
const INTERMEDIATE_RE = /\bdraft\b|\bwip\b|\bold\b|\btemp\b|\btest\b|copy\s*\d*$|\bv0*1\b/i;

const W = { FINAL_FILENAME: 0.35, MOST_RECENT: 0.20, MANIFEST_MATCH: 0.15, NOT_DUPLICATE: 0.10,
            AI_CONF_WEIGHT: 0.20, EXACT_DUP_PENALTY: -0.30, INTERMEDIATE_PENALTY: -0.20 };
const THRESH_FINAL = 0.72, THRESH_REVIEW_LOW = 0.40, MARGIN = 0.08;

function normalizeForWordMatch(name) { return (name || "").replace(/[_\-.]+/g, " "); }

function mostRecentInFamily(asset, all) {
  if (!asset.version_cluster_id) return false;
  const family = all.filter(a => a.version_cluster_id === asset.version_cluster_id);
  if (family.length < 2) return false;
  const newest = family.reduce((a, b) => ((a.modified_at || "") > (b.modified_at || "") ? a : b));
  return newest.id === asset.id;
}

function scoreAsset(asset, all) {
  const reasons = [];
  let score = 0;
  const nameNorm = normalizeForWordMatch(asset.filename);

  if (FINAL_RE.test(nameNorm)) { score += W.FINAL_FILENAME; reasons.push(`filename matches a final-like pattern (+${W.FINAL_FILENAME})`); }
  if (mostRecentInFamily(asset, all)) { score += W.MOST_RECENT; reasons.push(`most recently modified file in its version family (+${W.MOST_RECENT})`); }
  if (asset.validation && asset.validation.matched_deliverable) { score += W.MANIFEST_MATCH; reasons.push(`matches an expected deliverable in the project manifest (+${W.MANIFEST_MATCH})`); }

  const isExactDup = !!(asset.exact_duplicate_of && asset.exact_duplicate_of.length);
  if (!isExactDup) { score += W.NOT_DUPLICATE; reasons.push(`not an exact duplicate of another asset (+${W.NOT_DUPLICATE})`); }
  else { score += W.EXACT_DUP_PENALTY; reasons.push(`is an exact duplicate of another asset (${W.EXACT_DUP_PENALTY})`); }

  if (INTERMEDIATE_RE.test(nameNorm)) { score += W.INTERMEDIATE_PENALTY; reasons.push(`filename matches an intermediate/draft-like pattern (${W.INTERMEDIATE_PENALTY})`); }

  let aiConfidenceUsed = false;
  const ai = asset.ai;
  if (ai && (ai.ai_mode === "live" || ai.ai_mode === "mock")) {
    const member = (ai.members || []).find(m => m.asset_id === asset.id);
    if (member && member.likely_role === "final") {
      const contribution = W.AI_CONF_WEIGHT * (member.role_confidence || 0);
      score += contribution;
      reasons.push(`AI (${ai.ai_mode}) rates this member as likely-final, confidence ${member.role_confidence} (+${contribution.toFixed(3)})`);
      aiConfidenceUsed = true;
    }
  }

  score = Math.max(0, Math.min(1, score));

  let status;
  if (asset.in_source_folder || asset.asset_type === "source_unsupported") status = "LIKELY_SOURCE";
  else if (asset.inspection_ok === false) status = "INVALID";
  else if (score >= THRESH_FINAL) status = "LIKELY_FINAL";
  else if (score >= THRESH_REVIEW_LOW) status = "NEEDS_REVIEW";
  else if (isExactDup) status = "DUPLICATE";
  else status = "LIKELY_INTERMEDIATE";

  const nearBoundary = Math.abs(score - THRESH_FINAL) <= MARGIN || Math.abs(score - THRESH_REVIEW_LOW) <= MARGIN;
  const unresolvedCluster = !!asset.version_cluster_id && (!ai || ai.ai_mode === "failed");
  const requiresReview = (
    status === "NEEDS_REVIEW" || nearBoundary || unresolvedCluster ||
    (ai != null && ai.ai_mode === "failed") ||
    (!!(asset.visually_similar_to && asset.visually_similar_to.length) && !aiConfidenceUsed)
  );

  return { status, score: Math.round(score * 1000) / 1000, requires_review: !!requiresReview, reasons };
}

const payload = $json;
for (const a of payload.assets) a.classification = scoreAsset(a, payload.assets);
return [{ json: payload }];

const a = $json;
a.final_status = (a.classification.status === "LIKELY_FINAL") ? "approved_auto" : "excluded_auto";
a.review_decision = null;
return { json: a };

const items = $input.all().map(i => i.json);

const rows = items.map(a => {
  const dupOf = (a.exact_duplicate_of && a.exact_duplicate_of.length) ? a.exact_duplicate_of.join(", ")
    : ((a.visual_duplicate_of || []).map(d => d.asset_id).join(", "));
  return `<tr><td><code>${a.id}</code></td><td><strong>${a.filename}</strong><br><span style="color:#666;font-size:11px">${a.relpath}</span></td>` +
    `<td>${a.classification.status}</td><td>${a.classification.score}</td>` +
    `<td style="font-size:12px">${(a.classification.reasons || []).join('; ')}</td>` +
    `<td>${dupOf || '&mdash;'}</td>` +
    `<td style="font-size:12px">${(a.ai && a.ai.visual_summary) ? a.ai.visual_summary : '&mdash;'}</td></tr>`;
}).join("");

const html = `<div style="font-family:ui-monospace,monospace;font-size:13px">
<table style="border-collapse:collapse;width:100%" border="1" cellpadding="6">
<tr style="background:#eee"><th>Asset ID</th><th>File</th><th>Status</th><th>Score</th><th>Why flagged</th><th>Duplicate of</th><th>AI summary</th></tr>
${rows}</table>
<p>${items.length} asset(s) need a decision. Edit the JSON template below: set "action" for each
asset_id to one of <b>approve | reject | mark_final | mark_duplicate | exclude | rename_category</b>,
then paste the edited JSON into the field below and submit.</p></div>`;

const template = {};
for (const a of items) template[a.id] = { action: "", note: "" };

return [{ json: { review_html: html, decisions_template: JSON.stringify(template, null, 2), queue: items } }];

const queue = $('Aggregate Review Queue').item.json.queue;
let decisionsRaw = $json['Decisions (JSON)'] || '{}';
let decisions = {};
try {
  const parsed = JSON.parse(decisionsRaw);
  decisions = parsed.decisions || parsed;
} catch (e) {
  decisions = {}; // malformed submission -- every item below falls through to pending_review, never silently delivered
}

const VALID_ACTIONS = new Set(["approve", "reject", "mark_final", "mark_duplicate", "exclude", "rename_category"]);

return queue.map(a => {
  const d = decisions[a.id];
  if (d) {
    const action = VALID_ACTIONS.has(d.action) ? d.action : "exclude"; // unrecognized action fails safe to exclude
    a.review_decision = { action, note: d.note || null, by: "human" };
    if (action === "approve" || action === "mark_final") {
      a.final_status = "approved_reviewed";
      if (action === "mark_final") a.classification.status = "LIKELY_FINAL";
    } else if (action === "rename_category") {
      a.final_status = "approved_reviewed";
      a.delivery_category_override = d.category || null;
    } else {
      a.final_status = "excluded";
      if (action === "mark_duplicate") a.classification.status = "DUPLICATE";
    }
  } else {
    a.review_decision = null;
    a.final_status = "pending_review"; // no decision submitted -- never auto-delivered
  }
  return { json: a };
});

const det = $('Merge AI Results Onto Asset List').item.json;
const assets = $input.all().map(i => i.json);
const combined = { ...det, assets };
return [{ json: { content: JSON.stringify(combined, null, 2) } }];

const cfg = $('Project Configuration').item.json;
return [{ json: {
  status: "complete",
  output_dir: cfg.output_dir,
  delivery_manifest_html: `${cfg.output_dir}/delivery_manifest.html`,
  delivery_manifest_json: `${cfg.output_dir}/delivery_manifest.json`,
  processing_report_html: `${cfg.output_dir}/processing_report.html`,
  delivery_folder: `${cfg.output_dir}/delivery`,
}}];
